    return dict(name=name, code=code, dept=dept, reason=reason, reports=reports, admit=admit, days=days, wards=wards,
                meds=meds, outcome=outcome, cost=cost, surgery=surgery, ages=ages, weight=weight, blood=blood, med_cost=med_cost, ttype=ttype)

